-- Owner-approved small serving photographs. Image paths only; no prices or options change.
UPDATE products SET settings=jsonb_set(jsonb_set(settings, '{image_url}', CASE WHEN settings->>'image_url'='/assets/enbishan-menu/source-64b60282a385143c.jpg' THEN to_jsonb('/assets/enbishan-menu/owner-20261026-plates/potato.webp'::text) ELSE COALESCE(settings->'image_url','null'::jsonb) END), '{variant_images}', COALESCE((SELECT jsonb_agg(CASE WHEN v->>'image_url'='/assets/enbishan-menu/source-64b60282a385143c.jpg' THEN jsonb_set(v,'{image_url}',to_jsonb('/assets/enbishan-menu/owner-20261026-plates/potato.webp'::text)) ELSE v END ORDER BY ord) FROM jsonb_array_elements(COALESCE(settings->'variant_images','[]'::jsonb)) WITH ORDINALITY t(v,ord)), '[]'::jsonb)) WHERE brand_id='enbishan' AND (settings->>'image_url'='/assets/enbishan-menu/source-64b60282a385143c.jpg' OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(settings->'variant_images','[]'::jsonb)) v WHERE v->>'image_url'='/assets/enbishan-menu/source-64b60282a385143c.jpg'));
